//! Compare the composed scripted single-word reads and caller gate with native rows.
use spore_core::{cell_restore_stream_gate_v1::{self as gate,Action,Resolver},cell_stream_word_read_v1 as word};
fn w(b:&[u8],o:usize)->u32{u32::from_le_bytes(b[o..o+4].try_into().unwrap())}
fn main(){let mut args=std::env::args().skip(1);let b=std::fs::read(args.next().expect("native rows")).unwrap();let input=u32::from_str_radix(&args.next().expect("synthetic Input address"),16).unwrap();let root=u32::from_str_radix(&args.next().expect("synthetic Backend+8 address"),16).unwrap();assert_eq!(b.len(),576);for i in 0..12{let k=i%6;let cw=if i>=6{0x37f}else{0x27f};let f=word::project(0,input,k!=0,match k{0=>None,1=>Some((2,(input&0xffff0000)|0x2211)),2=>Some((4,0)),_=>Some((4,0x01000000))},true).unwrap();let second=if f.destination==0{None}else{Some(word::project(0,root,k!=3,match k{3=>None,4=>Some((2,(root&0xffff0000)|0x2211)),_=>Some((4,0x00efcdab))},true).unwrap())};let resolver=second.as_ref().map(|_|Resolver{succeeded:true,slot_after:0x55});let x=gate::project(true,0xa5a5a5a5,Some(f.destination),second.as_ref().map(|r|r.destination),resolver,Some(true),cw,0x1f80,true).unwrap();let row=&b[i*48..(i+1)*48];let read=f.read_calls+second.as_ref().map_or(0,|r|r.read_calls);let sync=f.sync_calls+second.as_ref().map_or(0,|r|r.sync_calls);let status=f.status_calls+second.as_ref().map_or(0,|r|r.status_calls);let resolve=x.actions.iter().filter(|a|matches!(a,Action::Resolve{..})).count() as u32;let end=x.actions.iter().filter(|a|matches!(a,Action::End)).count() as u32;assert_eq!((w(row,0),w(row,4),w(row,8),w(row,12),w(row,16),w(row,28),w(row,32),w(row,36)),(u32::from(x.returned),x.slot,read,resolve,end,0x10001,sync,status));assert_eq!((w(row,40),w(row,44)),if let Some(s)=second{(f.destination,s.destination)}else{(0,0)});let fp=w(row,20);assert_eq!(fp&0xffff,cw as u32);assert_eq!((fp>>16)&0x3840,0);assert_eq!(w(row,24)&!0x3f,0x1f80);}println!("matched twelve scripted caller/helper partial and error rows; synthetic addresses and callbacks admitted");}
